import * as THREE from './three.module.js';
import {surfaceHeight} from './physics.js?v=16';
import {regions} from './layout.js?v=16';
export function createAtmosphere(scene,world){
 const group=new THREE.Group();group.name='living-environment';scene.add(group);const clock={value:0};
 const leafColors=new Set(['d6537e','b73768','ed869e','ba426e','e36f91']);
 const touched=new Set();world.garden.traverse(o=>{if(!o.isMesh||!o.material?.color||!leafColors.has(o.material.color.getHexString())||touched.has(o.material))return;const m=o.material;touched.add(m);m.onBeforeCompile=shader=>{shader.uniforms.uBreeze=clock;shader.vertexShader='uniform float uBreeze;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n transformed.x += sin(uBreeze*1.1+position.x*.7+position.z*.4)*.035*smoothstep(1.8,3.0,position.y); transformed.z += cos(uBreeze*.8+position.x*.5)*.022*smoothstep(1.8,3.0,position.y);');};m.customProgramCacheKey=()=> 'gentle-blossom-breeze';m.needsUpdate=true;});
 const starPositions=new Float32Array(260*3);for(let i=0;i<260;i++){const a=i*2.399,rad=35+(i%11)*2;starPositions[i*3]=Math.cos(a)*rad;starPositions[i*3+1]=12+(i%29)*.8;starPositions[i*3+2]=Math.sin(a)*rad;}
 const sg=new THREE.BufferGeometry();sg.setAttribute('position',new THREE.BufferAttribute(starPositions,3));const stars=new THREE.Points(sg,new THREE.PointsMaterial({color:'#d8e6ff',size:.075,transparent:true,opacity:.64,depthWrite:false}));group.add(stars);
 const sea=new THREE.Mesh(new THREE.PlaneGeometry(150,150,60,60),new THREE.ShaderMaterial({uniforms:{uTime:clock},vertexShader:'uniform float uTime; varying vec3 vWorld; void main(){vec3 p=position;p.z+=sin(p.x*.25+uTime*.28)*.035+cos(p.y*.2+uTime*.2)*.03;vWorld=p;gl_Position=projectionMatrix*modelViewMatrix*vec4(p,1.0);}',fragmentShader:'uniform float uTime; varying vec3 vWorld; void main(){float ripple=pow(max(0.,sin(vWorld.x*.55+vWorld.y*.21+uTime*.4)),18.);float glow=exp(-length(vWorld.xy-vec2(0.,-6.))*.025);vec3 c=mix(vec3(.055,.075,.13),vec3(.075,.12,.19),glow)+ripple*.006;gl_FragColor=vec4(c,1.);}'}));sea.rotation.x=-Math.PI/2;sea.position.y=-.98;group.add(sea);
 const glowGeometry=new THREE.CircleGeometry(1,24),glows=new THREE.InstancedMesh(glowGeometry,new THREE.MeshBasicMaterial({color:'#ffd396',transparent:true,opacity:.055,depthWrite:false}),20);const dummy=new THREE.Object3D();let k=0;
 for(const region of regions)for(let i=0;i<4;i++){const a=i*Math.PI/2+.6,x=region.x+Math.sin(a)*4.3,z=region.z+Math.cos(a)*4.3;dummy.position.set(x,surfaceHeight(x,z)+.012,z);dummy.rotation.set(-Math.PI/2,0,0);dummy.scale.setScalar(.72);dummy.updateMatrix();glows.setMatrixAt(k++,dummy.matrix);}group.add(glows);
 const routeDots=new THREE.InstancedMesh(new THREE.SphereGeometry(.055,6,4),new THREE.MeshBasicMaterial({color:'#ffe0a7',transparent:true,opacity:.7,depthWrite:false}),64);routeDots.count=0;routeDots.frustumCulled=false;group.add(routeDots);
 const motes=new THREE.InstancedMesh(new THREE.OctahedronGeometry(.045,0),new THREE.MeshBasicMaterial({color:'#ffd3db',transparent:true,opacity:.75,depthWrite:false}),36);motes.frustumCulled=false;group.add(motes);const particles=Array.from({length:36},()=>({life:0,x:0,y:0,z:0,vx:0,vy:0,vz:0}));let next=0,stepDistance=0;
 function particle(x,y,z,burst){const p=particles[next++%particles.length],a=next*2.399;p.x=x;p.y=y;p.z=z;p.vx=Math.sin(a)*(burst?1.6:.2);p.vz=Math.cos(a)*(burst?1.6:.2);p.vy=burst?1.5+(next%4)*.3:.25;p.life=burst?1.1:.45;}
 function route(points,start){let out=0,from=start;for(const end of points){const len=Math.hypot(end.x-from.x,end.z-from.z);for(let d=.65;d<len&&out<64;d+=.65){const t=d/len,x=from.x+(end.x-from.x)*t,z=from.z+(end.z-from.z)*t;dummy.position.set(x,surfaceHeight(x,z)+.08,z);dummy.rotation.set(0,0,0);dummy.scale.setScalar(1);dummy.updateMatrix();routeDots.setMatrixAt(out++,dummy.matrix);}from=end;if(out===64)break;}routeDots.count=out;routeDots.instanceMatrix.needsUpdate=true;}
 return {route,celebrate(position){for(let i=0;i<22;i++)particle(position.x,position.y+.5,position.z,true);},update(time,dt,motion,player,{reduced=false,showRoute=true}={}){
  clock.value=reduced?0:time;stars.material.opacity=reduced?.5:.50+Math.sin(time*.3)*.08;routeDots.visible=showRoute;
  if(motion.distance<stepDistance)stepDistance=motion.distance;
  if(!reduced&&motion.grounded&&motion.distance-stepDistance>.58){stepDistance=motion.distance;if(motion.speed>1)particle(player.position.x,surfaceHeight(motion.x,motion.z)+.06,player.position.z,false);}
  for(let i=0;i<particles.length;i++){const p=particles[i];p.life=Math.max(0,p.life-dt);if(p.life&&!reduced){p.vy-=dt*1.4;p.x+=p.vx*dt;p.y+=p.vy*dt;p.z+=p.vz*dt;}dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(time+i,time*.5,0);dummy.scale.setScalar(reduced?0:Math.min(1,p.life*3));dummy.updateMatrix();motes.setMatrixAt(i,dummy.matrix);}motes.instanceMatrix.needsUpdate=true;
 }};
}
